"""Register bounded primary affinity documentation and actual producer inspection."""
import hashlib,json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[4];BASE=Path(__file__).resolve().parent
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def write(p,v):p.write_text(json.dumps(v,indent=2)+'\n',encoding='utf-8',newline='\n')
def main():
 rows=[
 ('R-LSB-AFFINITY','Linux sched_setaffinity(2)','https://man7.org/linux/man-pages/man2/sched_setaffinity.2.html','Linux man-pages6.19, dated2026-02-08',['DESCRIPTION: per-thread eligible CPU set and migration when the current CPU is excluded','ERRORS EINVAL and NOTES: actual present/permitted CPU intersection and cpuset restrictions','EXAMPLES opening: measured execution depends on CPU placement and cache effects'],'Actual primary manual passages inspected. No claim that the teaching cooperative mask API is syscall-equivalent or that measured duration isolates cache misses.'),
 ('R-LSB-PTHREAD-AFFINITY','Linux pthread_setaffinity_np(3)','https://man7.org/linux/man-pages/man3/pthread_setaffinity_np.3.html','Linux man-pages6.19, dated2025-09-21',['DESCRIPTION and RETURN VALUE: per-thread mask, migration and nonzero error number','STANDARDS and NOTES: GNU nonportable API, kernel restrictions and inherited mask'],'Actual primary manual passages inspected; host affinity is verifier machinery, not an implementation of the first-principles scheduler.'),
 ('R-LSB-C11','WG14 N1570 C11 draft','https://www.open-std.org/jtc1/sc22/wg14/www/docs/n1570.pdf','12April2011 committee draft',['5.1.2.4 paragraphs5–13/PDF36: synchronization, release sequence and reads-from','5.1.2.4 paragraphs16–25/PDF37–38: happens-before/coherence and data races'],'Actually inspected bounded draft passages reused; no newly inspected exact published C17 text or target MMIO inference.'),
 ('R-LSB-PRODUCERS','Original completed queue, wakeup and lock contracts','labs/smp_depth/queues/CONTRACTS.md','Current T53.05/T53.06/T53.07 successors',['queues/CONTRACTS.md: READY/RUNNING/TRANSFER ownership, two-sided reservations and saved-context boundary','wakeup/CONTRACTS.md: MOVING, SIGNAL after committed work and notification-only retry','locks/CONTRACTS.md: stable guard lifetime and acquire/release TAS'],'Actual complete producer contracts and bounded implementation functions read before composing; no fresh exhaustive retained-kernel verification.')]
 resources=[]
 for rid,title,url,edition,locators,limits in rows:resources.append({'id':rid,'title':title,'authors':['Primary document owners or original curriculum contributors'],'url':url,'edition':edition,'domains':['T53'],'locators':locators,'kind':'documentation','access':'Actual bounded primary passages inspected','role':'primary','assignable':True,'reason':'Separate C publication, stopped-context ownership, operating-system affinity and qualified observations.','prerequisites':['PR-T53-05','PR-T53-06','PR-T53-07'],'inspection':{'date':'2026-10-18','method':'Actual named primary documentation and original contracts/implementation passages read before authorship.','scope':'; '.join(locators),'limits':limits}})
 write(BASE/'resources.json',{'schema_version':1,'resources':resources,'reference_gaps':['Exact readable published C17 remains unavailable.','No selected physical PMU/cache topology or WCET experiment; observations retain virtual/native process scope.']})
 contracts=[ROOT/'labs/smp_depth'/p/'CONTRACTS.md' for p in ('queues','wakeup','locks')]
 write(BASE/'source_access.json',{'schema_version':1,'date':'2026-10-18','actual_web_passages':[rows[0][2],rows[1][2]],'prerequisite_contract_sha256':{p.relative_to(ROOT).as_posix():sha(p) for p in contracts},'private_document_sha256':{'build/legacy_runtime_sources/n1570.pdf':sha(ROOT/'build/legacy_runtime_sources/n1570.pdf')},'original_analysis':'The finite policy, deferred-mask boundary, timer lease, cost example and tests are original course analysis; they are not attributed to unseen scheduler literature.','scope':'Only the named bounded primary passages inspected; no physical observation or independent human review.'})
 write(BASE/'research_gate.json',{'status':'passage-inspected','domains':['T53'],'inspection_kind':'Author passage inspection, not independent human review','research_input_sha256':{p.relative_to(ROOT).as_posix():sha(p) for p in (BASE/'resources.json',BASE/'source_access.json')}})
 print(json.dumps({'resources':len(resources)}))
if __name__=='__main__':main()
